'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const reduced=matchMedia('(prefers-reduced-motion: reduce)');
const KEYS={saved:'lsatu-studio-saved',recent:'lsatu-studio-recent',prep:'lsatu-studio-prep',progress:'lsatu-studio-progress',plans:'lsatu-studio-plans'};
const bank=[
{id:'LR-155-1-1',kind:'LR',test:'155',section:'1',number:'1',topic:'Necessary assumptions',title:'The reading room',text:'A library will extend its evening hours. Its director predicts that more students will visit because students often ask for somewhere quiet to study after dinner.',ask:'Which assumption is required by the director’s prediction?',choices:['Every student prefers a library to any other study space.','At least some students who want a quiet place can reach the library during its extended hours.','The library is already the busiest study space in the city.'],answer:1,hint:'Wanting somewhere quiet is one thing. Being able to use this particular library is another. Which answer connects them?',explanation:'If none of those students can get to the library during the new hours, their requests give the director no reason to predict more visits.'},
{id:'LR-154-2-2',kind:'LR',test:'154',section:'2',number:'2',topic:'Argument structure',title:'The community garden',text:'The neighbourhood garden produced more vegetables after its volunteers added compost. The coordinator concludes that the compost caused the increase, although this summer also brought more rain.',ask:'Which possibility most directly challenges the coordinator’s reasoning?',choices:['Rainfall, rather than compost, may explain the larger harvest.','Some volunteers prefer growing flowers.','Compost can be made from garden waste.'],answer:0,hint:'The harvest increased. What else changed besides the compost? Look for a different possible cause.',explanation:'The extra rainfall is an alternative explanation. If it caused the increase, the coordinator has not shown that the compost did.'},
{id:'RC-153-3-3',kind:'RC',test:'153',section:'3',number:'3',topic:'Passage purpose',title:'Reading a city',text:'Old street maps can preserve more than the shape of a city. Their omissions sometimes reveal which neighbourhoods their makers considered important. A historian who compares several maps can therefore learn about changing priorities as well as changing streets.',ask:'What is the main purpose of this passage?',choices:['To explain how to draw an accurate street map.','To argue that modern maps are unreliable.','To describe how maps can reveal historical priorities.'],answer:2,hint:'Look at what the whole passage does. Does it teach mapmaking, criticize modern maps, or explain something a historian can learn?',explanation:'The passage describes a use for old maps: their omissions can tell historians which places mattered to the people who made them.'}
];
function read(key,fallback){try{const v=localStorage.getItem(key);return v===null?fallback:JSON.parse(v)}catch{return fallback}}
function write(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true}catch{toast('This browser could not save your change. Keep this tab open.');$('.save-label').textContent='Changes only in this tab';return false}}
function validIds(value){return Array.isArray(value)?[...new Set(value.filter(id=>bank.some(q=>q.id===id)))]:[]}
let saved=validIds(read(KEYS.saved,[])),recent=validIds(read(KEYS.recent,[]));
let prep=read(KEYS.prep,'');if(typeof prep!=='string')prep='';
let progress=read(KEYS.progress,5);if(!Number.isInteger(progress)||progress<5||progress>12)progress=5;
let plans=read(KEYS.plans,{});if(!plans||typeof plans!=='object'||Array.isArray(plans))plans={};
let toastTimer,opener,currentQuestion,currentList='all',currentSet=0,currentDay=0,drillAnswered=false;
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const ref=q=>`PT ${q.test} · ${q.kind} · S${q.section} · Q${q.number}`;
const icon=name=>`<svg aria-hidden="true"><use href="#${name}"/></svg>`;
function toast(message){clearTimeout(toastTimer);$('.toast').textContent=message;$('.toast').classList.add('visible');toastTimer=setTimeout(()=>$('.toast').classList.remove('visible'),3500)}
function panel(kicker,title,html){if(!$('#panel').open)opener=document.activeElement;$('#panel-kicker').textContent=kicker;$('#panel-title').textContent=title;$('#panel-body').innerHTML=html;if(!$('#panel').open){$('#panel').showModal();if(!reduced.matches)$('#panel').animate([{opacity:.7,transform:'translateY(10px)'},{opacity:1,transform:'translateY(0)'}],{duration:220,easing:'cubic-bezier(.22,1,.36,1)'});}$('#panel-title').focus();}
function closePanel(){$('#panel').close()}
$('.close').onclick=closePanel;
$('#panel').addEventListener('click',e=>{if(e.target===$('#panel')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closePanel()}});
$('#panel').addEventListener('close',()=>{const id=opener?.dataset.question;updateShelf();updatePrep();if(opener?.isConnected)opener.focus();else if(id){const replacement=$$('[data-question]').find(e=>e.dataset.question===id);(replacement||$('.library-search')).focus()}});
function updateProgress(){const done=progress===12;$('#resume-number').textContent=Math.min(progress+1,12);$('#hero-progress-copy').textContent=`${progress} of 12 complete`;$$('.progress-track i').forEach((tick,i)=>tick.classList.toggle('complete',i<progress));if(done){$('.hero-cta').innerHTML=`Review completed practice<span class="button-icon">${icon('arrow')}</span>`;$('.light-pill').innerHTML='<span></span> Practice complete';}}
function updatePrep(){$('#prep-preview').textContent=prep||'Bring the question that stayed with you.'}
let shelfMode='samples';
function updateShelf(){$('#saved-count').textContent=saved.length;const ids=shelfMode==='saved'?saved.slice(0,2):shelfMode==='recent'?recent.slice(0,2):[bank[0].id,bank[1].id];$('#question-shelf').innerHTML=ids.length?ids.map(id=>{const q=bank.find(x=>x.id===id);return `<button class="question-ticket" data-question="${q.id}"><span class="ticket-ref">PT ${q.test} / S${q.section} / Q${q.number}</span>${icon(saved.includes(id)?'bookmark':'arrow')}<small>${q.topic}</small></button>`}).join(''):`<p class="shelf-empty">${shelfMode==='saved'?'Open a sample and save it here for another look.':'Questions you open will appear here.'}</p>`;$('.shelf-heading h3').textContent=shelfMode==='saved'?'Saved for another look':shelfMode==='recent'?'Back to your last question':'Try a sample question';$$('[data-shelf]').forEach(b=>{b.classList.toggle('selected',b.dataset.shelf===shelfMode);b.setAttribute('aria-pressed',String(b.dataset.shelf===shelfMode))})}

function openSearch(list='all'){currentList=list;panel('Question library · Original sample content','Find your next question.',`<label class="input-label" for="question-search">Search by reference or topic</label><input id="question-search" class="search-input" type="search" placeholder="Try assumptions or PT 155" autocomplete="off"><div class="dialog-tabs" role="group" aria-label="Question list"><button data-list="all">All samples</button><button data-list="saved">Saved questions</button><button data-list="recent">Recently opened</button></div><div id="search-results" aria-live="polite"></div><p class="demo-note">Three original demonstration questions. The live question bank is not connected.</p>`);$('#question-search').addEventListener('input',renderResults);renderResults();$('#question-search').focus()}
function renderResults(){const query=$('#question-search').value.trim().toLowerCase();const pool=currentList==='all'?bank:(currentList==='saved'?saved:recent).map(id=>bank.find(q=>q.id===id));const found=pool.filter(q=>(ref(q)+' '+q.topic+' '+q.title).toLowerCase().includes(query));$$('[data-list]').forEach(b=>{b.classList.toggle('selected',b.dataset.list===currentList);b.setAttribute('aria-pressed',String(b.dataset.list===currentList))});$('#search-results').innerHTML=found.length?found.map(q=>`<button class="search-result" data-question="${q.id}"><span><small>${ref(q)}</small><strong>${q.topic}</strong></span>${icon('arrow')}</button>`).join(''):`<p class="empty-state">${query?'No matching sample questions. Try “155”, “structure” or “reading”.':currentList==='saved'?'Your saved questions will live here. Open any sample and choose Save question.':'Questions you open will appear here. Choose All samples to get started.'}</p>`}
function question(q){currentQuestion=q;recent=[q.id,...recent.filter(id=>id!==q.id)].slice(0,6);write(KEYS.recent,recent);panel(ref(q),q.title,`<div class="sample-notice">Original demonstration question. Not official PrepTest content.</div><p class="question-stimulus">${q.text}</p><p class="question-ask">${q.ask}</p><fieldset class="answers"><legend class="sr-only">Choose an answer</legend>${q.choices.map((c,i)=>`<label><input type="radio" name="answer" value="${i}"><span>${String.fromCharCode(65+i)}.</span>${c}</label>`).join('')}</fieldset><div class="question-actions"><button class="check-answer">Check answer</button><button class="save-question" aria-pressed="${saved.includes(q.id)}">${saved.includes(q.id)?'Saved question':'Save question'}</button><button class="session-question">Bring to session</button></div><p class="answer-feedback" role="status"></p><button class="back-search">← Back to question library</button>`)}
function session(){panel('Saturday, October 24 · 7:15 pm · 60 minutes','Bring the sticking point.',`<p>You don’t need a polished question. A sentence you couldn’t explain, or two answers you couldn’t separate, is enough.</p><label class="input-label" for="prep">What would you like to work through with Joshua?</label><textarea id="prep" class="panel-input" placeholder="I kept coming back to…" maxlength="1500"></textarea><div class="panel-status" role="status"></div><button class="button dark panel-button" data-action="done">Done ${icon('check')}</button><p class="demo-note">Saved on this device. Nothing is sent to Joshua from this prototype.</p>`);$('#prep').value=prep;$('.panel-status').textContent=prep?(read(KEYS.prep,'')===prep?'Your preparation is saved on this device.':'Not saved. Keep this tab open and try editing your note again.'):'Your note saves here as you type.';$('#prep').addEventListener('input',()=>{prep=$('#prep').value;const ok=write(KEYS.prep,prep);$('.panel-status').textContent=ok?'Saved on this device.':'Not saved. This browser could not store your note.';updatePrep()})}
const drillPrompts=[{sentence:'Every volunteer attends the briefing.',choices:['No volunteers attend the briefing.','At least one volunteer does not attend the briefing.','Some volunteers attend the briefing.'],answer:1,hint:'To make “every” false, do you need zero volunteers attending, or just one exception?',explanation:'One volunteer who does not attend is enough to make “every volunteer attends” false.'},{sentence:'Some readers enjoy every chapter.',choices:['No reader enjoys every chapter.','Every reader enjoys no chapters.','Some readers dislike every chapter.'],answer:0,hint:'Keep the complete condition “enjoys every chapter” together. What would make it false that anyone meets that condition?',explanation:'The original claims at least one reader enjoys every chapter. Its negation says no reader does.'},{sentence:'The library is open on Saturday.',choices:['The library is open on Sunday.','The library is always closed.','The library is not open on Saturday.'],answer:2,hint:'Change only the claim about Saturday. Other days do not decide whether it is true.',explanation:'“Not open on Saturday” denies exactly the original statement, without adding claims about other days.'}];
function drill(){if(progress===12){panel('Negation Station · Sample practice complete','A clearer way to test.',`<p>You completed the local demonstration. To negate a claim, make that precise claim false. Don’t replace it with a stronger opposite.</p><p>For an assumption question, then ask what happens to the argument without that assumption.</p><button class="button dark panel-button" data-action="done">Back to your studio ${icon('arrow')}</button><p class="demo-note">This demonstration cycles through three original prompts. No live course progress was changed.</p>`);return;}drillAnswered=false;const q=drillPrompts[(progress-5)%3];panel('Negation Station · Original demonstration',`Prompt ${progress+1} of 12`, `<div class="drill-progress">${progress} complete · Your place saves on this device</div><p>Choose the statement that makes this claim false.</p><p class="question-stimulus"><strong>${q.sentence}</strong></p><fieldset class="answers"><legend class="sr-only">Choose a negation</legend>${q.choices.map((c,i)=>`<label><input type="radio" name="drill-answer" value="${i}"><span>${String.fromCharCode(65+i)}.</span>${c}</label>`).join('')}</fieldset><div class="question-actions"><button class="check-answer" data-drill="check">Check negation</button><button data-drill="leave">Save and leave</button></div><p class="answer-feedback" role="status"></p><p class="demo-note">Local practice demonstration with three sample prompts.</p>`)}
function recall(){panel('Reading recall · Original demonstration','Read. Pause. Remember.',`<p>Read this paragraph. When you are ready, hide it and recall its main point and how the sentences connect.</p><div class="reading-passage">Old street maps can preserve more than the shape of a city. Their omissions sometimes reveal which neighbourhoods their makers considered important. Comparing several maps can therefore show a historian how those priorities changed.</div><button class="button dark panel-button" data-reading="hide">Recall paragraph ${icon('arrow')}</button><p class="demo-note">No timer, score or recording. Take the time you need.</p>`)}
const sets=[{score:9,total:10,topic:'Necessary assumptions',date:'October 23',question:0},{score:6,total:8,topic:'Argument structure',date:'October 22',question:1},{score:5,total:8,topic:'Reading comprehension',date:'October 21',question:2}];
function setChart(index){currentSet=index;const s=sets[index];$('#chart-score').innerHTML=`${s.score}<span>/${s.total}</span>`;$('#chart-description').innerHTML=`${s.topic}<br>${s.date}`;$('#review-label').textContent=`${s.total-s.score} question${s.total-s.score===1?'':'s'} to revisit`;$$('[data-set]').forEach(b=>{const on=+b.dataset.set===index;b.classList.toggle('selected',on);b.setAttribute('aria-pressed',String(on))});}
const days=[{day:'SAT',date:24,title:'Your session with Joshua',copy:'7:15 pm · Bring your questions.',action:'session',mark:true},{day:'SUN',date:25,title:'Room to think.',copy:'An open day. Add one intention or leave it open.',action:'plan'},{day:'MON',date:26,title:'Read. Pause. Remember.',copy:'Reading recall · One paragraph at a time.',action:'recall',mark:true},{day:'TUE',date:27,title:'Follow your curiosity.',copy:'Pick a question you want to understand.',action:'search'},{day:'WED',date:28,title:'Find the flaw.',copy:'Guided drill · Eight arguments.',action:'flaw',mark:true},{day:'THU',date:29,title:'Space for a question.',copy:'Add a study intention for this day.',action:'plan'},{day:'FRI',date:30,title:'A fresh look.',copy:'Return to the questions you saved.',action:'saved',mark:true}];
const fullDays=['Saturday','Sunday','Monday','Tuesday','Wednesday','Thursday','Friday'];
$('.week').innerHTML=days.map((d,i)=>`<button class="day${i===0?' selected':''}" data-day="${i}" aria-label="${fullDays[i]}, October ${d.date}" aria-pressed="${i===0}"><span>${d.day}</span><strong>${d.date}</strong><small>${['Session','Open','Recall','Questions','Flaw drill','Open','Review'][i]}</small><i style="visibility:${d.mark?'visible':'hidden'}"></i></button>`).join('');
function selectDay(index){currentDay=index;const d=days[index];$$('[data-day]').forEach(b=>{b.classList.toggle('selected',+b.dataset.day===index);b.setAttribute('aria-pressed',String(+b.dataset.day===index))});$('#agenda-date').textContent=`${fullDays[index]}, October ${d.date}`;$('#agenda-title').textContent=typeof plans[index]==='string'&&plans[index]?plans[index]:d.title;$('#agenda-copy').textContent=typeof plans[index]==='string'&&plans[index]?'Your saved study intention.':d.copy;updateDayLabels();}
function plan(){panel(`Your week · ${fullDays[currentDay]}, October ${days[currentDay].date}`,'Make a little room.',`<label class="input-label" for="day-plan">One study intention</label><input id="day-plan" class="panel-input" maxlength="120" placeholder="Return to that assumption question"><button class="button dark panel-button" data-action="save-plan">Save intention ${icon('check')}</button><p class="demo-note">Stored locally in this prototype.</p>`);$('#day-plan').value=typeof plans[currentDay]==='string'?plans[currentDay]:'';$('#day-plan').focus()}
const actions={search:()=>openSearch(),saved:()=>openSearch('saved'),session,resume:drill,recall,flaw:()=>question(bank[1]),plan,practice:()=>{panel('Make your own next step','What are you curious about?',`<div class="practice-choices"><button class="search-result" data-question="${bank[0].id}"><span><small>Logical reasoning</small><strong>What does the argument need?</strong></span>${icon('arrow')}</button><button class="search-result" data-question="${bank[1].id}"><span><small>Logical reasoning</small><strong>Where does the reasoning break?</strong></span>${icon('arrow')}</button><button class="search-result" data-action="recall"><span><small>Reading comprehension</small><strong>Read, pause, remember.</strong></span>${icon('arrow')}</button></div><p class="demo-note">Original local demonstrations, not live assigned work.</p>`);},note:()=>panel('A note from Joshua · Sample content','Try the opposite.',`<blockquote class="note-quote">“Don’t ask whether it sounds right. Ask what happens without it.”</blockquote><p>Negating an assumption helps you test whether the argument needs it. Change only what the sentence claims, then ask whether the reasoning still holds.</p><button class="button dark panel-button" data-action="resume">Try a prompt ${icon('arrow')}</button>`),inbox:()=>{actions.note();$('.notification-dot').hidden=true;$('.inbox-button').setAttribute('aria-label','Open Joshua’s note')},profile:()=>panel('Your study studio','Ada’s space.',`<p>This is a local interactive design prototype. Your saved questions, session notes and sample drill progress stay in this browser.</p><p>No account, official question bank or production records are connected.</p><button class="button dark panel-button" data-action="done">Back to studying ${icon('arrow')}</button>`),done:closePanel,'review-set':()=>question(bank[sets[currentSet].question]),'save-plan':()=>{const value=$('#day-plan').value.trim();const nextPlans={...plans,[currentDay]:value};if(write(KEYS.plans,nextPlans)){plans=nextPlans;selectDay(currentDay);closePanel();toast(value?'Study intention saved.':'Day left open.')}}};
document.addEventListener('click',e=>{const shelf=e.target.closest('[data-shelf]');if(shelf){shelfMode=shelf.dataset.shelf;updateShelf();return}const action=e.target.closest('[data-action]');if(action){actions[action.dataset.action]?.();return}const q=e.target.closest('[data-question]');if(q){question(bank.find(x=>x.id===q.dataset.question));return}const list=e.target.closest('[data-list]');if(list){currentList=list.dataset.list;renderResults();return}const f=e.target.closest('[data-filter]');if(f){$$('[data-filter]').forEach(x=>{x.classList.toggle('selected',x===f);x.setAttribute('aria-pressed',String(x===f))});$$('[data-assignment]').forEach(x=>x.hidden=f.dataset.filter!=='all'&&x.dataset.kind!==f.dataset.filter);$('.count-badge').textContent=String($$('[data-assignment]').filter(x=>!x.hidden).length).padStart(2,'0');return}const a=e.target.closest('[data-assignment]');if(a){actions[a.dataset.assignment]();return}const s=e.target.closest('[data-set]');if(s){setChart(+s.dataset.set);return}const day=e.target.closest('[data-day]');if(day){selectDay(+day.dataset.day);return}const drillAction=e.target.closest('[data-drill]');if(drillAction){if(drillAction.dataset.drill==='leave'){closePanel();return}if(drillAction.dataset.drill==='next'){drill();return}if(drillAnswered)return;const checked=$('input[name="drill-answer"]:checked');const q=drillPrompts[(progress-5)%3];if(!checked){$('.answer-feedback').textContent='Choose a negation first.';return}if(+checked.value!==q.answer){$('.answer-feedback').textContent=q.hint;return}drillAnswered=true;progress++;write(KEYS.progress,progress);updateProgress();$('.answer-feedback').textContent='Correct. '+q.explanation;drillAction.dataset.drill='next';drillAction.textContent=progress===12?'Finish practice':'Next prompt';return}if(e.target.closest('.check-answer')){const selected=$('input[name="answer"]:checked');$('.answer-feedback').textContent=!selected?'Choose an answer first.':+selected.value===currentQuestion.answer?'Correct. '+currentQuestion.explanation:currentQuestion.hint;return}if(e.target.closest('.save-question')){const id=currentQuestion.id;const nextSaved=saved.includes(id)?saved.filter(x=>x!==id):[id,...saved];const ok=write(KEYS.saved,nextSaved);if(!ok)return;saved=nextSaved;shelfMode='saved';const b=e.target.closest('.save-question');b.setAttribute('aria-pressed',String(saved.includes(id)));b.textContent=saved.includes(id)?'Saved question':'Save question';updateShelf();if(ok)toast(saved.includes(id)?'Kept on your question shelf.':'Removed from your saved shelf.');return}if(e.target.closest('.session-question')){const entry=`${currentQuestion.topic} (${ref(currentQuestion)}): What made the other answer tempting?`;if(!prep.includes(ref(currentQuestion))){const nextPrep=prep?prep+'\n\n'+entry:entry;if(nextPrep.length>1500){toast('Your note is full. Open session preparation to make room.');return}prep=nextPrep;}write(KEYS.prep,prep);updatePrep();session();return}if(e.target.closest('.back-search')){openSearch();return}const reading=e.target.closest('[data-reading]');if(reading){const box=$('.reading-passage');if(reading.dataset.reading==='hide'){box.dataset.text=box.textContent;box.textContent='Look away and recall the paragraph. What was its main point? How did the final sentence follow from the earlier ones?';box.classList.add('recalling');reading.dataset.reading='show';reading.innerHTML=`Show paragraph ${icon('book')}`;}else{box.textContent=box.dataset.text;box.classList.remove('recalling');reading.dataset.reading='hide';reading.innerHTML=`Recall paragraph ${icon('arrow')}`;}}});
$('#agenda-action').onclick=()=>actions[days[currentDay].action]();
$$('[data-day]').forEach((b,i)=>b.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const index=e.key==='Home'?0:e.key==='End'?6:(i+(e.key==='ArrowRight'?1:6))%7;selectDay(index);$(`[data-day="${index}"]`).focus()}));
const form=$('#reference-form');form.addEventListener('change',e=>{if(e.target.name==='kind'){form.elements.section.innerHTML=form.elements.kind.value==='LR'?'<option>1</option><option>2</option>':'<option>3</option>';}});form.addEventListener('submit',e=>{e.preventDefault();const id=`${form.elements.kind.value}-${form.elements.test.value}-${form.elements.section.value}-${form.elements.question.value}`;const match=bank.find(q=>q.id===id);if(match){question(match);return}panel('Question library · Demo bank','That reference isn’t in this demo.',`<p>The prototype contains three original sample questions. It does not contain the official question at your selected reference.</p><div>${bank.map(q=>`<button class="search-result" data-question="${q.id}"><span><small>${ref(q)}</small><strong>${q.topic}</strong></span>${icon('arrow')}</button>`).join('')}</div>`)});
$('.mobile-menu').onclick=()=>{const expanded=$('.mobile-menu').getAttribute('aria-expanded')==='true';$('.mobile-menu').setAttribute('aria-expanded',String(!expanded));$('#mobile-nav').hidden=expanded};$$('#mobile-nav a').forEach(a=>a.onclick=()=>{$('#mobile-nav').hidden=true;$('.mobile-menu').setAttribute('aria-expanded','false')});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openSearch()}});
updateProgress();updatePrep();updateShelf();setChart(0);

function updateDayLabels(){$$('[data-day]').forEach(b=>{const i=+b.dataset.day,d=days[i];const custom=typeof plans[i]==='string'&&plans[i];b.querySelector('small').textContent=custom?'Planned':['Session','Open','Recall','Questions','Flaw drill','Open','Review'][i];b.querySelector('i').style.visibility=custom||d.mark?'visible':'hidden';b.setAttribute('aria-label',`${fullDays[i]}, October ${d.date}: ${custom||d.title}`)})}
updateDayLabels();
$$('.desktop-nav a').forEach(a=>a.addEventListener('click',()=>{$$('.desktop-nav a').forEach(n=>{n.classList.toggle('active',n===a);if(n===a)n.setAttribute('aria-current','location');else n.removeAttribute('aria-current')})}));
